/* UI intentionally uses no framework; the calculation engine is shared with the CLI. */
'use strict';
const $=id=>document.getElementById(id),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LABELS={missing_tracker:'Нет в трекере',missing_advertiser:'Нет у рекламодателя',snapshot_conflict:'Конфликт снимков',invalid_click:'Клик не найден / дубль',identity_mismatch:'Разные ID / дата FTD',status_mismatch:'Разные статусы',multiple_ftd:'Несколько FTD игрока',missing_contract:'Нет договора',overlapping_contract:'Пересечение договоров',player_mismatch:'Другой игрок',invalid_registration:'Нет корректной регистрации',registration_window:'Регистрация позже 30 дней',deposit_window:'FTD позже 90 дней',not_last_click:'Не последний клик',currency_mismatch:'Несовпадение валют',below_min_deposit:'Депозит ниже порога',amount_mismatch:'Не совпадает сумма CPA',reversed:'Комиссия отозвана',rejected:'Конверсия отклонена',pending:'Ожидает подтверждения'};
const EXPLAIN={missing_tracker:'У рекламодателя есть конверсия, но соответствующий conversion_id в трекере отсутствует. Проверьте полноту выгрузки и маппинг идентификаторов.',missing_advertiser:'Конверсия есть только в трекере. Проверьте задержку отчёта, доставку postback и основание CPA-квалификации. Ожидаемая сумма не признаётся доходом.',snapshot_conflict:'У одного ID противоречивые версии с одинаковой датой или меняется идентичность события. Автоматический выбор заблокирован.',invalid_click:'Связанный click_id отсутствует или повторяется. Невозможно надёжно установить партнёра и атрибуцию.',identity_mismatch:'В источниках различаются click_id, player_id или occurred_at. События нельзя считать достоверно сопоставленными.',status_mismatch:'Текущие статусы источников различаются. При отсутствии блокирующих ошибок финансовый статус берётся у рекламодателя.',multiple_ftd:'Игрок отмечен несколькими разными conversion_id первого депозита. Все такие события исключены до ручного разбора.',missing_contract:'Для партнёра, оффера, страны и даты FTD не найден договор.',overlapping_contract:'На одну дату подходит больше одного договора. Выбор ставки заблокирован.',player_mismatch:'Игрок конверсии отличается от игрока регистрации по связанному клику.',invalid_registration:'Регистрация отсутствует, ещё не известна на дату среза или наступила позже FTD.',registration_window:'Между кликом и регистрацией прошло больше 30 × 24 часов. Учебная граница окна включена.',deposit_window:'Между регистрацией и FTD прошло больше 90 × 24 часов. Учебная граница окна включена.',not_last_click:'В загруженных данных есть более поздний клик того же игрока и оффера до регистрации.',currency_mismatch:'Валюта источника не соответствует договору. Суммы не конвертируются и не включаются в доверенные итоги.',below_min_deposit:'Сумма депозита не достигает учебного порога договора. Факт депозита сам по себе не означает оплачиваемую CPA-конверсию.',amount_mismatch:'Approved-сумма рекламодателя отличается от ставки. В проверенные итоги входит его фактическая сумма, если нет блокирующих ошибок.',reversed:'Последний известный статус отменяет текущее начисление. Это не расчёт возврата уже выплаченных денег.',rejected:'Рекламодатель отклонил конверсию. Ожидаемая ставка показана только для проверки причины.',pending:'Начисление ещё не подтверждено. Выплата и проверенное начисление равны нулю.'};
let data=structuredClone(window.DEMO_DATA),result=null,page=0,view='overview',applied={asOf:'2026-11-24',start:'2026-04-01',end:'2026-11-24',partner:''};
const fmt=n=>new Intl.NumberFormat(I18N.locale).format(n),money=(n,cur='GBP')=>new Intl.NumberFormat(I18N.locale,{style:'currency',currency:cur,maximumFractionDigits:2,minimumFractionDigits:0}).format(n/100);
const notify=t=>{$('notice').textContent=t;I18N.apply();};
function download(name,text,type='text/csv;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function go(v){view=v;document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==v);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));try{history.replaceState(null,'','#'+v);}catch{if(location.hash!=='#'+v)location.hash=v;}if(v==='review')renderReview();window.scrollTo(0,0);I18N.apply();}
function badge(f){return '<span class="badge '+(['snapshot_conflict','currency_mismatch','identity_mismatch','multiple_ftd'].includes(f)?'danger':'')+'">'+E(LABELS[f]||f)+'</span>';}
function refreshPartners(){const previous=$('partner').value,partners=[...new Set(data.clicks.map(x=>x.partner_id))].sort();$('partner').innerHTML='<option value="">Все партнёры</option>'+partners.map(x=>'<option value="'+E(x)+'">'+E(x)+'</option>').join('');if(partners.includes(previous))$('partner').value=previous;}
function run(){const candidate={asOf:$('asof').value,start:$('start').value,end:$('end').value,partner:$('partner').value};try{const next=Recon.reconcile(data,candidate);result=next;applied=candidate;page=0;notify('');const selected=$('currency').value;const cs=result.finance.map(x=>x.currency);$('currency').innerHTML=(cs.length?cs:['GBP']).map(x=>'<option>'+E(x)+'</option>').join('');if(cs.includes(selected))$('currency').value=selected;render();return true;}catch(e){notify(e.message);return false;}}
function render(){
 const cur=$('currency').value,f=result.finance.find(x=>x.currency===cur)||{recognized_cents:0,partner_cents:0,margin_cents:0,due_cents:0,held_cents:0,exposure_cents:0};
 const stats=[['Проверенные начисления',f.recognized_cents,'Approved после обязательных проверок','accent'],['Выплаты партнёрам',f.partner_cents,'По ставкам договора, включая hold',''],['Разница начислений и выплат',f.margin_cents,'До налогов и операционных расходов',''],['Потенциал сверки',f.exposure_cents,'Ожидаемое минус approved. Не доход.','warning']];
 $('stats').innerHTML=stats.map(([l,v,s,c])=>'<article class="stat '+c+'"><div class="label">'+l+'</div><div class="value">'+E(money(v,cur))+'</div><div class="sub">'+s+'</div></article>').join('');
 const issues=Object.entries(result.counts).sort((a,b)=>b[1]-a[1]),n=result.ledger.filter(x=>x.flags.length).length;$('navCount').textContent=n;$('issueTotal').textContent=fmt(n)+' конверсий';const mx=Math.max(1,...issues.map(x=>x[1]));
 $('issues').innerHTML=issues.length?issues.slice(0,6).map(([k,v])=>'<div class="bar-line"><span>'+E(LABELS[k])+'</span><div class="bar-track"><div class="bar-fill" style="width:'+v/mx*100+'%"></div></div><strong>'+fmt(v)+'</strong></div>').join(''):'<div class="empty">Расхождений в выбранном срезе нет.</div>';
 $('bridgeSubtitle').textContent='Валюта '+cur+' · срез '+result.cutoff;
 $('bridge').innerHTML=[['Approved после проверок',f.recognized_cents],['Выплаты после hold',f.due_cents],['Выплаты на hold',f.held_cents],['Остаток до расходов',f.margin_cents]].map(([k,v])=>'<div class="bridge-row"><span>'+k+'</span><strong>'+E(money(v,cur))+'</strong></div>').join('');
 const groups=new Map();for(const r of result.ledger.filter(r=>r.currency===cur)){if(!groups.has(r.partner_id))groups.set(r.partner_id,{n:0,issues:0,recognized:0,pay:0,margin:0});const g=groups.get(r.partner_id);g.n++;g.issues+=!!r.flags.length;g.recognized+=r.recognized_cents;g.pay+=r.partner_cents;g.margin+=r.margin_cents;}
 $('partnerRows').innerHTML=[...groups].sort((a,b)=>b[1].recognized-a[1].recognized).map(([p,g])=>'<tr><td class="partner-name">'+E(p)+'</td><td class="num">'+fmt(g.n)+'</td><td class="num">'+fmt(g.issues)+'</td><td class="num">'+E(money(g.recognized,cur))+'</td><td class="num">'+E(money(g.pay,cur))+'</td><td class="num">'+E(money(g.margin,cur))+'</td></tr>').join('')||'<tr><td colspan="6" class="empty">Нет данных для выбранного периода.</td></tr>';
 $('partnerTotal').textContent=groups.size+' партнёра';const z=result.funnel;
 $('funnel').innerHTML=[['Клики',z.clicks,''],['Регистрации',z.registrations,z.clicks?(z.registrations/z.clicks*100).toFixed(1)+'% от кликов':''],['Игроки с FTD',z.ftd,z.registrations?(z.ftd/z.registrations*100).toFixed(1)+'% от регистраций':'']].map(([l,v,s])=>'<div class="funnel-item"><span>'+l+'</span><strong>'+fmt(v)+'</strong><span>'+s+'</span></div>').join('');
 $('snapshotNote').textContent='Весь комплект на дату среза: '+fmt(result.meta.trackerUnique)+' ID трекера, '+fmt(result.meta.advertiserUnique)+' ID рекламодателя · '+result.meta.duplicates+' повторов доставки · '+result.meta.ignored+' будущих снимков исключено. Эти счётчики не зависят от фильтра партнёра и периода.';
 const reason=$('reason').value;$('reason').innerHTML='<option value="">Все расхождения</option>'+issues.map(([k,v])=>'<option value="'+k+'">'+E(LABELS[k])+' ('+v+')</option>').join('');if(issues.some(x=>x[0]===reason))$('reason').value=reason;
 renderReview();renderImports();I18N.apply();
}
function selection(){const search=$('search').value.toLowerCase(),reason=$('reason').value,show=$('show').value;return result.ledger.filter(r=>(!search||[r.conversion_id,r.player_id,r.click_id].some(x=>x.toLowerCase().includes(search)))&&(!reason||r.flags.includes(reason))&&(show==='all'||(show==='issues'?r.flags.length:!r.flags.length))).sort((a,b)=>b.day.localeCompare(a.day)||a.conversion_id.localeCompare(b.conversion_id));}
function renderReview(){if(!result)return;const rs=selection(),pages=Math.max(1,Math.ceil(rs.length/25));page=Math.min(page,pages-1);$('reviewRows').innerHTML=rs.slice(page*25,page*25+25).map(r=>'<tr><td><strong>'+E(r.conversion_id)+'</strong><small>'+r.day+'</small></td><td>'+E(r.partner_id)+'</td><td>'+E(r.tracker_status)+'<small>'+E(r.advertiser_status)+'</small></td><td class="num">'+E(money(r.expected_cents,r.currency))+'</td><td class="num">'+E(money(r.reported_cents,r.reported_currency||r.currency))+'</td><td class="flags-cell">'+(r.flags.length?r.flags.map(badge).join(''):'<span class="badge good">Сопоставлено</span>')+'</td><td><button class="detail-button" data-id="'+E(r.conversion_id)+'">Разбор</button></td></tr>').join('')||'<tr><td colspan="7" class="empty">По этому запросу конверсий нет.</td></tr>';$('rowCount').textContent=fmt(rs.length)+' записей';$('pageNumber').textContent=(page+1)+' / '+pages;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;I18N.apply();}
function openDetail(id){const r=result.ledger.find(r=>r.conversion_id===id);if(!r)return;$('detailTitle').textContent=id;$('detailBody').innerHTML='<p>'+E(r.partner_id)+' · '+r.day+' · '+E(r.currency)+'</p>'+'<div class="detail-metrics">'+[['Ожидаемый CPA',r.expected_cents],['Проверено',r.recognized_cents],['Выплата партнёру',r.partner_cents]].map(([k,v])=>'<div>'+k+'<strong>'+E(money(v,r.currency))+'</strong></div>').join('')+'</div>'+(r.flags.length?r.flags.map(f=>'<div class="explanation"><strong>'+E(LABELS[f])+'</strong>'+E(EXPLAIN[f])+'</div>').join(''):'<p class="badge good">Обязательные проверки пройдены. Источники сопоставлены.</p>')+'<h3>Исходные записи</h3><p class="note">Все снимки по ID, включая будущие. Срез расчёта: '+result.cutoff+'.</p><pre>'+E(JSON.stringify({tracker:data.tracker.filter(x=>x.conversion_id===id),advertiser:data.advertiser.filter(x=>x.conversion_id===id),clicks:data.clicks.filter(x=>x.click_id===r.click_id),contracts:data.contracts.filter(x=>x.partner_id===r.partner_id&&x.offer_id===r.offer_id)},null,2))+'</pre>';$('detail').showModal();I18N.apply();}
const SOURCE_INFO={clicks:['Клики и регистрации','Одна строка на click_id. player_id и registered_at пусты для незарегистрированных.'],tracker:['FTD из трекера','Снимки первого депозита. deposit_amount — депозит, не размер CPA.'],advertiser:['Отчёт рекламодателя','Снимки статуса и начисления. amount — CPA, не депозит и не GGR.'],contracts:['Договорные ставки','Одна ставка на партнёра, оффер, страну и диапазон дат FTD.']};
function renderImports(){for(const k of Object.keys(SOURCE_INFO)){const count=$('count_'+k);if(count)count.textContent=fmt(data[k].length)+' строк в текущем наборе';}}
function initImports(){$('importCards').innerHTML=Object.entries(SOURCE_INFO).map(([k,[title,desc]])=>'<article class="import-card"><h2>'+title+'</h2><p>'+desc+'</p><div class="source-count" id="count_'+k+'"></div><code>'+Recon.SCHEMA[k].join(', ')+'</code><label>Файл '+k+'.csv<input type="file" id="file_'+k+'" accept=".csv,text/csv"></label><button class="quiet source-download" data-sample="'+k+'">Скачать пример</button></article>').join('');}
function exportRows(rows,name){download(name,Recon.csv(rows.map(r=>{const o={...r,flags:r.flags.join('|')};for(const k of Object.keys(o).filter(k=>k.endsWith('_cents'))){o[k.replace('_cents','')]=(o[k]/100).toFixed(2);delete o[k];}return o;})));}
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));document.querySelector('.brand').onclick=e=>{e.preventDefault();go('overview');};$('goReview').onclick=()=>go('review');$('filters').onsubmit=e=>{e.preventDefault();run();};$('currency').onchange=()=>render();
for(const id of ['search','reason','show'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;renderReview();});$('prev').onclick=()=>{page--;renderReview();};$('next').onclick=()=>{page++;renderReview();};$('reviewRows').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openDetail(b.dataset.id);};$('closeDetail').onclick=()=>$('detail').close();
$('exportLedger').onclick=()=>exportRows(result.ledger,'ledger_'+result.cutoff+'.csv');$('exportReview').onclick=()=>exportRows(selection(),'exceptions_'+result.cutoff+'.csv');
$('exportAudit').onclick=()=>download('audit_'+result.cutoff+'.json',JSON.stringify({application:'Ledger 1.0.0',options:applied,model:'CPA network demonstrator; no actual payments or RevShare',result},null,2),'application/json');
$('importCards').addEventListener('click',e=>{const k=e.target.closest('[data-sample]')?.dataset.sample;if(k)download(k+'.csv',Recon.csv(window.DEMO_DATA[k],Recon.SCHEMA[k]));});
$('applyImport').onclick=async()=>{const button=$('applyImport');button.disabled=true;try{const input={};for(const k of Object.keys(Recon.SCHEMA)){const file=$('file_'+k).files[0];if(!file)throw new Error('Выберите файл '+k+'.csv');if(file.size>20*1024*1024)throw new Error(file.name+': файл больше 20 МБ');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());input[k]=Recon.parseCSV(text);Recon.validate(k,input[k]);}const next=Recon.reconcile(input,{asOf:$('asof').value,start:$('start').value,end:$('end').value,partner:''});data=input;result=next;refreshPartners();$('partner').value='';applied={asOf:$('asof').value,start:$('start').value,end:$('end').value,partner:''};run();go('overview');notify('Комплект загружен. Проверьте даты среза и отчётного периода.');}catch(e){notify('Загрузка отменена. '+e.message);}finally{button.disabled=false;}};
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{I18N.setLanguage(b.dataset.language);render();if($('detail').open)openDetail($('detailTitle').textContent);}));
initImports();refreshPartners();run();I18N.apply();if(['overview','review','import','method'].includes(location.hash.slice(1)))go(location.hash.slice(1));
